import json
import re
from itertools import combinations

def parse_examples_to_train_labels(facts_str):
    """Parse facts string to extract train IDs."""
    trains = set()
    for line in facts_str.split():
        if line.startswith('has_car('):
            m = re.match(r'has_car\((\w+)', line)
            if m:
                trains.add(m.group(1))
    return sorted(trains)

def build_validation_program(examples):
    """Build a Prolog validation program from (facts_string, label) pairs."""
    blocks = []
    for facts_str, label in examples:
        facts = [f.strip() + '.' for f in facts_str.split('.') if f.strip()]
        train_id = None
        for fact in facts:
            m = re.match(r'has_car\((\w+)', fact)
            if m:
                train_id = m.group(1)
                break
        if train_id:
            block = [f"{label}({train_id})."] + facts
        else:
            block = facts
        blocks.append('\n'.join(block))
    return '\n\n'.join(blocks) + '\n\n'

def build_feature_space(examples):
    """Build the feature space from examples."""
    all_preds = {}  # predicate_name -> { arg_index: set of values }
    all_train_ids = set()

    for facts_str, label in examples:
        facts = re.findall(r'(\w+)\(([^)]+)\)', facts_str)
        for pred, args_str in facts:
            args = [a.strip() for a in args_str.split(',')]
            if pred not in all_preds:
                all_preds[pred] = {}
            for i, arg in enumerate(args):
                if i not in all_preds[pred]:
                    all_preds[pred][i] = set()
                all_preds[pred][i].add(arg)
            if pred == 'has_car':
                all_train_ids.add(args[0])

    return all_preds, all_train_ids

# Test building candidate rules
with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

demo = demos[0]
from rewards.slr_bench import parse_prompt_examples

result = parse_prompt_examples(demo['prompt'])
examples = list(zip(result['inputs'], result['outputs']))

preds, trains = build_feature_space(examples)
print("Predicates found:", list(preds.keys()))

# Generate candidate single-literal body: car_len(C, short), car_color(C, red), etc.
# We want predicates where arg1 is a car (or the predicate itself takes a car variable)
# The rule is: eastbound(T) :- has_car(T, C), <body_literal>.
# So body literals should be about cars C, and optionally about trains T

# Generate all possible body literals of the form predicate(arg1, arg2) where
# arg1 could be T (train) or C (car)

def generate_body_literals(preds):
    """Generate all possible body literal strings."""
    literals = []
    for pred, arg_vals in preds.items():
        if pred == 'has_car':
            continue  # Always present as structural
        n_args = len(arg_vals)
        # Try with car variable C and train variable T
        for v1 in arg_vals.get(1, set()):
            for v2 in arg_vals.get(2, set()):
                if n_args == 2:
                    literals.append(f"{pred}(C, {v2})")
                    literals.append(f"{pred}(T, {v2})")
                elif n_args == 1:
                    literals.append(f"{pred}(C, {v1})")
                    literals.append(f"{pred}(T, {v1})")
    return literals

literals = generate_body_literals(preds)
print("\nCandidate literals:")
for l in literals[:20]:
    print(f"  {l}")

# Generate candidate rules
def generate_candidate_rules(literals):
    """Generate candidate rules with 1 to N body literals."""
    candidates = []
    for n in range(1, min(len(literals) + 1, 4)):
        for combo in combinations(literals, n):
            body = ', '.join(combo)
            candidates.append(f"eastbound(T) :- has_car(T, C), {body}.")
    return candidates

rules = generate_candidate_rules(literals)
print(f"\nTotal candidate rules: {len(rules)}")
for r in rules[:10]:
    print(f"  {r}")

