import re

def generate_body_literals(preds):
    """Generate all possible body literal strings."""
    literals = []
    for pred, arg_vals in preds.items():
        if pred == 'has_car':
            continue  # Always present as structural glue

        # Check arg types
        arg1_vals = arg_vals.get(1, set())
        arg2_vals = arg_vals.get(2, set())
        arg3_vals = arg_vals.get(3, set())

        # Heuristic: if arg1 contains car references (words containing 'car'),
        # then arg2 contains the property values
        # If arg1 contains train references (words containing 'train'),
        # then it's a train-level predicate

        is_car_predicate = False
        is_train_predicate = False

        # Check if arg1 values are car IDs
        if arg1_vals:
            has_car_refs = any('car' in str(v) and v[0].islower() and not v.startswith('train') for v in arg1_vals)
            has_train_refs = any('train' in str(v) and v[0].islower() for v in arg1_vals)

            # If arg2 values are NOT car/train IDs (they're property values)
            if arg2_vals:
                arg2_has_props = not any('car' in str(v) for v in arg2_vals)
                if has_car_refs and arg2_has_props:
                    is_car_predicate = True
                elif has_train_refs and arg2_has_props:
                    is_train_predicate = True

        if is_car_predicate:
            # Generate literals with C variable
            for val in arg2_vals:
                literals.append(f"{pred}(C, {val})")
            # For car_num, might want to use car_num(C, N)

        if is_train_predicate:
            for val in arg2_vals:
                literals.append(f"{pred}(T, {val})")

    return literals

