        train_id = None
        for fact in facts:
            m = re.match(r'has_car\((\w+)', fact)
            if m:
                train_id = m.group(1)
                break
        if train_id:
            block = [f"{label}({train_id})."] + facts
        else:
            block = facts
        blocks.append('\n'.join(block))
    return '\n\n'.join(blocks) + '\n\n'

def build_feature_space(examples):
    all_preds = {}
    for facts_str, label in examples:
        facts = re.findall(r'(\w+)\(([^)]+)\)', facts_str)
        for pred, args_str in facts:
            args = [a.strip() for a in args_str.split(',')]
            if pred not in all_preds:
                all_preds[pred] = {}
            for i, arg in enumerate(args):
                if i not in all_preds[pred]:
                    all_preds[pred][i] = set()
                all_preds[pred][i].add(arg)
    return all_preds

def generate_body_literals(preds):
    literals = []
    for pred, arg_vals in preds.items():
        if pred == 'has_car':
            continue
        arg0_vals = arg_vals.get(0, set())
        arg1_vals = arg_vals.get(1, set())

        is_car_predicate = False
        is_train_predicate = False

        if arg0_vals:
            has_car_refs = any('car' in str(v) and v[0].islower() and not v.startswith('train') for v in arg0_vals)
            has_train_refs = any('train' in str(v) for v in arg0_vals)

            if arg1_vals:
                arg1_has_props = not any('car' in str(v) for v in arg1_vals)
                if has_car_refs and arg1_has_props:
                    is_car_predicate = True
                elif has_train_refs and arg1_has_props:
                    is_train_predicate = True

        if is_car_predicate:
            for val in arg1_vals:
                literals.append(f"{pred}(C, {val})")

        if is_train_predicate:
            for val in arg1_vals:
                literals.append(f"{pred}(T, {val})")

    return literals

def generate_candidate_rules(literals, max_body_literals=4):
