    for n in range(1, min(len(literals) + 1, max_body_literals + 1)):
        for combo in combinations(literals, n):
            body = ', '.join(combo)
            candidates.append(f"eastbound(T) :- has_car(T, C), {body}.")
    return candidates

# Test on first 5 demos
